package com.example.financetracker.controller;

import com.example.financetracker.model.*; import com.example.financetracker.repository.*; import com.example.financetracker.service.CurrentUserService;
import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.time.*; import java.util.*; import java.util.stream.*;
@RestController @RequestMapping("/api") public class DashboardController {
 private final TransactionRepository tx;private final BudgetRepository budgets;private final CurrentUserService current;
 public DashboardController(TransactionRepository t,BudgetRepository b,CurrentUserService c){tx=t;budgets=b;current=c;}
 @GetMapping("/dashboard/summary") public Map<String,Object> summary(@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to){LocalDate start=from==null?LocalDate.now().withDayOfMonth(1):from;LocalDate end=to==null?LocalDate.now():to;var list=tx.findByUserIdAndTransactionDateBetweenOrderByTransactionDateDesc(current.get().getId(),start,end);BigDecimal income=sum(list,TransactionType.INCOME),expense=sum(list,TransactionType.EXPENSE);Map<String,Object> m=new LinkedHashMap<>();m.put("from",start);m.put("to",end);m.put("income",income);m.put("expenses",expense);m.put("balance",income.subtract(expense));m.put("transactions",list.size());m.put("categoryExpenses",categoryExpenses(list));m.put("monthlyTrends",monthlyTrends());m.put("recentTransactions",list.stream().limit(8).map(t->Map.of("id",t.getId(),"type",t.getType(),"amount",t.getAmount(),"category",t.getCategory(),"description",Objects.toString(t.getDescription(),""),"transactionDate",t.getTransactionDate())).toList());return m;}
 @GetMapping("/analytics/category-expenses") public List<Map<String,Object>> categories(){return categoryExpenses(tx.findByUserIdOrderByTransactionDateDescCreatedAtDesc(current.get().getId()));}
 @GetMapping("/analytics/monthly-trends") public List<Map<String,Object>> trends(){return monthlyTrends();}
 private BigDecimal sum(List<FinanceTransaction> l,TransactionType type){return l.stream().filter(t->t.getType()==type).map(FinanceTransaction::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);}
 private List<Map<String,Object>> categoryExpenses(List<FinanceTransaction> l){Map<String,BigDecimal> m=l.stream().filter(t->t.getType()==TransactionType.EXPENSE).collect(Collectors.groupingBy(FinanceTransaction::getCategory,TreeMap::new,Collectors.reducing(BigDecimal.ZERO,FinanceTransaction::getAmount,BigDecimal::add)));return m.entrySet().stream().map(e->Map.<String,Object>of("category",e.getKey(),"amount",e.getValue())).toList();}
 private List<Map<String,Object>> monthlyTrends(){LocalDate end=LocalDate.now().withDayOfMonth(1).plusMonths(1).minusDays(1),start=end.withDayOfMonth(1).minusMonths(5);var l=tx.findByUserIdAndTransactionDateBetweenOrderByTransactionDateDesc(current.get().getId(),start,end);List<Map<String,Object>> out=new ArrayList<>();for(int i=5;i>=0;i--){LocalDate m=LocalDate.now().withDayOfMonth(1).minusMonths(i);var part=l.stream().filter(t->t.getTransactionDate().getYear()==m.getYear()&&t.getTransactionDate().getMonth()==m.getMonth()).toList();out.add(Map.of("month",m.toString().substring(0,7),"income",sum(part,TransactionType.INCOME),"expenses",sum(part,TransactionType.EXPENSE)));}return out;}
}
